const data = JSON.parse(query);

const riskScore = Number(data.RISK_SCORE || 0);
const riskLevel = data.RISK_LEVEL || "UNKNOWN";

const indicators = [];

if (riskScore >= 30) {
  indicators.push("High-value transaction");
}

if (data.TRANSACTION_LOCATION !== data.CUSTOMER_CITY) {
  indicators.push("Geographic mismatch");
}

if (data.DEVICE_ID && data.DEVICE_ID !== "D001") {
  indicators.push("Unusual device detected");
}

return JSON.stringify({
  transaction_id: data.TRANSACTION_ID,
  risk_score: riskScore,
  risk_level: riskLevel,
  risk_indicators: indicators,
  investigation_status: riskLevel === "HIGH"
    ? "Requires investigation"
    : "No immediate investigation required"
});
